t.script:
document.getElementById('btn_check_role').addEventListener('click', function () {
    var btn = this;
    btn.disabled = true;
    btn.innerHTML = ' ตรวจสอบสิทธิ์';
    fetch('/iam/check-role', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({jsonrpc: '2.0', method: 'call', params: {}}),
    })
    .then(function (r) { return r.json(); })
    .then(function (data) {
        if (data.result && data.result.has_role) {
            window.location = '/web';
        } else {
            btn.disabled = false;
            btn.textContent = 'ตรวจสอบสิทธิ์';
            alert('ยังไม่ได้รับสิทธิ์ กรุณาติดต่อผู้ดูแลระบบ');
        }
    })
    .catch(function () {
        btn.disabled = false;
        btn.textContent = 'ตรวจสอบสิทธิ์';
        alert('ไม่สามารถตรวจสอบได้ กรุณาลองใหม่อีกครั้ง');
    });
});
